<?php
namespace App\Http\Controllers\Admin;
use App\Enums\AssignmentStatus;use App\Http\Controllers\Controller;use App\Http\Requests\CancelAssignmentRequest;use App\Http\Requests\CompleteAssignmentRequest;use App\Http\Requests\StoreAssignmentRequest;use App\Models\Assignment;use App\Models\CustomerRequirement;use App\Models\DutyType;use App\Models\Service;use App\Models\Worker;use App\Services\ActivityLogger;use App\Services\AssignmentService;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class AssignmentController extends Controller { public function index(Request $request,string $scope='all'):View{$q=Assignment::with(['customer','worker','service','dutyType','requirement']);if($scope==='active')$q->whereIn('status',AssignmentStatus::active());if($scope==='history')$q->whereIn('status',AssignmentStatus::history());$q->when($request->filled('search'),function($q)use($request){$t='%'.$request->string('search')->trim().'%';$q->where(fn($x)=>$x->where('assignment_code','like',$t)->orWhereHas('customer',fn($c)=>$c->where('name','like',$t)->orWhere('mobile_number','like',$t))->orWhereHas('worker',fn($w)=>$w->where('name','like',$t)->orWhere('mobile_number','like',$t))->orWhereHas('requirement',fn($r)=>$r->where('requirement_code','like',$t)));})->when($request->filled('status'),fn($q)=>$q->where('status',$request->input('status')))->when($request->filled('service'),fn($q)=>$q->where('service_id',$request->integer('service')))->when($request->filled('duty_type'),fn($q)=>$q->where('duty_type_id',$request->integer('duty_type')))->when($request->filled('start_date'),fn($q)=>$q->whereDate('assignment_start_date',$request->input('start_date')));return view('admin.assignments.index',['assignments'=>$q->latest()->paginate(20)->withQueryString(),'statuses'=>AssignmentStatus::cases(),'services'=>Service::where('is_active',true)->get(),'dutyTypes'=>DutyType::where('is_active',true)->get(),'scope'=>$scope]);} public function active(Request $r):View{return $this->index($r,'active');}public function history(Request $r):View{return $this->index($r,'history');} public function create(CustomerRequirement $requirement,Worker $worker):View{$requirement->load(['customer','service','dutyType','workingCondition']);$worker->load('services');return view('admin.assignments.form',['requirement'=>$requirement,'worker'=>$worker,'dutyTypes'=>DutyType::where('is_active',true)->get()]);} public function store(StoreAssignmentRequest $request,CustomerRequirement $requirement,Worker $worker,AssignmentService $service,ActivityLogger $logger):RedirectResponse{$a=$service->create($requirement,$worker,$request->validated(),$request->user()->id);$logger->log('created','assignments',$a,'Assignment created.',['assignment_code'=>$a->assignment_code]);$logger->log($a->status===AssignmentStatus::Active?'started':'confirmed','assignments',$a,$a->status===AssignmentStatus::Active?'Assignment started immediately.':'Assignment confirmed.');return redirect()->route('admin.assignments.show',$a)->with('success','Assignment confirmed.');} public function show(Assignment $assignment):View{$assignment->load(['customer','worker','service','dutyType','requirement','statusHistory.changedBy','replacementRequests.oldWorker','replacementRequests.newWorker']);return view('admin.assignments.show',compact('assignment'));} public function start(Request $request,Assignment $assignment,AssignmentService $service,ActivityLogger $logger):RedirectResponse{abort_unless($request->user()->hasPermission('assignments.status'),403);$service->start($assignment,$request->user()->id);$logger->log('started','assignments',$assignment,'Assignment started.');return back()->with('success','Assignment started.');} public function complete(CompleteAssignmentRequest $request,Assignment $assignment,AssignmentService $service,ActivityLogger $logger):RedirectResponse{$service->complete($assignment,$request->validated('completion_date'),$request->validated('reason'),$request->user()->id);$logger->log('completed','assignments',$assignment,'Assignment completed.');return back()->with('success','Assignment completed.');} public function cancel(CancelAssignmentRequest $request,Assignment $assignment,AssignmentService $service,ActivityLogger $logger):RedirectResponse{$service->cancel($assignment,$request->validated('reason'),$request->validated('still_required'),$request->user()->id);$logger->log('cancelled','assignments',$assignment,'Assignment cancelled.');return back()->with('success','Assignment cancelled.');} }
